import { createHostedExecutorSessionClock, } from "./executor-session.js";
import { performanceMonotonicClock } from "../streaming/lifecycle/clock.js";
/** Honor forward UTC corrections without letting rollback extend elapsed budgets. */
export function createExecutorNodeClock(wallNow = () => Date.now(), elapsed = performanceMonotonicClock) {
    const clock = createHostedExecutorSessionClock(wallNow(), elapsed);
    let correction = 0;
    return {
        ...clock,
        now() {
            const elapsedNow = clock.now();
            const value = Math.max(elapsedNow + correction, wallNow());
            correction = value - elapsedNow;
            return value;
        },
    };
}
export const executorNodeClock = createExecutorNodeClock();
/**
 * Timer delivery can precede the clock deadline. Expire only once it is due.
 * Owners of UTC deadlines can bound idle observation with maxWakeDelayMs.
 */
export function scheduleExecutorNodeDeadline(clock, deadline, expire, maxWakeDelayMs = Number.POSITIVE_INFINITY) {
    let canceled = false;
    let handle;
    const wake = () => {
        if (canceled)
            return;
        const remaining = deadline - clock.now();
        if (remaining > 0) {
            handle = clock.schedule(wake, Math.min(remaining, maxWakeDelayMs));
            return;
        }
        canceled = true;
        expire();
    };
    handle = clock.schedule(wake, Math.min(maxWakeDelayMs, Math.max(0, deadline - clock.now())));
    return () => {
        if (canceled)
            return;
        canceled = true;
        clock.cancel(handle);
    };
}
